// Forge 3D car bodies for CITY DRIVER.
//
// Every car in the game is now generated by the Forge 3D car designer (js/forge/, vendored from
// jaykk99/forge3d): a lofted clearcoat body with real wheel arches, glass greenhouse, hinged hood,
// lights, bumpers, interior, engine bay and Forge wheels/tires. No stored models — each car is a
// written description turned into design numbers (cargen.designFromText) with a fixed seed, then
// sized to the game's handling dimensions so physics, collisions and the tuning parts still line up.
//
// buildForgeCar() returns a group with the exact same contract as the old procedural cars:
//   car faces -Z, wheels are direct children (rotation.x spins, rotation.y steers, front z < 0),
//   userData = { defId, bodyColor, wheels, frontWheels, rim, glass, paint, brakeMats, profile, frontZ, rearZ, ... }.
import * as THREE from 'three';
import { designFromText, profileFromDesign, designDims } from './forge/builders/cargen.js';
import { buildVehicle } from './forge/builders/vehicle.js';
import { tireSize } from './forge/builders/vehiclesim.js';
import { rimMaterial } from './forge/builders/wheel.js';
import { carPaint, glass as forgeGlass, lens, Q } from './forge/render/materials.js';
import { VEHICLE_DEFAULTS } from './forge/vehicleDefaults.js';
import { addCarDetail } from './forge/builders/cardetail.js';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';

// Phones get Forge's "balanced" mesh density (fewer loft stations / wheel segments); desktops get "high".
const touch = typeof matchMedia !== 'undefined' && matchMedia('(pointer:coarse)').matches;
Q.level = touch ? 'balanced' : 'high';

