const toHex = n => '#' + (n >>> 0).toString(16).padStart(6, '0').slice(-6);

// Turn a description + footprint into a full Forge parameter set.
export function forgeParamsFor(id, colorHex = 0xc01818){
  const spec = FORGE_DESIGNS[id] || FORGE_DESIGNS.sport;
  const d = designFromText(spec.text, spec.seed);
  const P = { ...VEHICLE_DEFAULTS, ...d, ...(spec.design || {}) };
  // footprint from the game
  P.length = spec.len; P.width = spec.W; P.wheelbase = Math.min(0.86, spec.wb / spec.len); P.overhangF = 0.5;
  // tire sized so its radius matches the game's wheel radius
  P.rimSize = spec.rimSize; P.tireWidthF = P.tireWidthR = spec.W > 1.95 ? 275 : 245;
  const rimR = P.rimSize * 0.0254 / 2;
  P.sidewall = Math.round(Math.max(25, Math.min(90, (spec.R - rimR) / (P.tireWidthF / 1000) * 100)));
  P.skinnies = false;
  P.rim = spec.rim; P.rimFinish = spec.rimFinish || (P.rimFinish === 'black' ? 'black' : 'polished'); P.tire = spec.tire || 'sport';
  if (P.tire === 'slick') P.tire = 'sport';           // road car look; slicks come from the tuning shop
  if (spec.headlights) P.headlights = spec.headlights;
  if (spec.spoiler) P.spoiler = spec.spoiler;
  if (spec.exhaust) P.exhaust = spec.exhaust;
  // the game draws its own light bars / bull bars / racks / wings from the tuning shop, keep the shell clean
  P.lightBar = false; P.bullBar = false; P.roofRack = id === 'suv'; P.rollCage = !!spec.rollCage; P.parachute = false; P.wheelieBar = false;
  P.lift = 0; P.hoodOpen = false; P.interior = true;
  P.paint = toHex(colorHex); P.finish = spec.finish || 'metallic';
  P.stripes = spec.stripes || 'none'; if (spec.stripeColor) P.stripeColor = spec.stripeColor;
  P.hd = true; P.tailBar = !!spec.tailBar; P.quadLights = !!spec.quadLights;
  return P;
}

// ---- template cache: build each car shape once, then clone (geometry shared, materials per car) ----
const templates = new Map();

function makeTemplate(id){
  const P = forgeParamsFor(id, 0xc01818);
  const root = buildVehicle({ id:'cd_' + id, type:'vehicle' }, P, {});
  const v = root.userData.vehicle;
  const dims = designDims(P);
  // materials Forge used for this car (its material cache hands back the same objects)
  const paintM = carPaint({ color:P.paint, finish:P.finish, flake:P.flake });
  const glassM = forgeGlass({ tint:P.tint, color:'#7f97a8' });
  const rimM = rimMaterial(P.rimFinish, P.rimColor);
  const tailM = lens('#c80a0a', 0.6);

  // game frame: the car faces -Z and the origin sits midway between the axles
  const zMid = (dims.axleF + dims.axleR) / 2;
  const body = new THREE.Group(); body.name = 'forgeBody';
  body.rotation.y = Math.PI;                   // Forge +Z front -> game -Z front
  body.position.z = zMid;                      // after the flip, world z = -(forgeZ) + zMid
  // detach the wheels: game wheels must be direct children of the car group
  const wheels = [];
  for (const w of v.wheels){
    const flip = w.pivot.children[0];          // holds the spinning wheel mesh
    w.pivot.remove(flip); root.remove(w.pivot);
    const holder = new THREE.Group(); holder.name = 'wheel';
    flip.rotation.y += Math.PI;                // undo the body flip so the rim face still points outward
    holder.add(flip);
    holder.position.set(-w.x, w.y, -(w.z - zMid));
    wheels.push(holder);
    // Forge's brake calipers are separate non-spinning parts; the game spins the whole wheel holder,
    // so they're dropped (the disc + rim still show through the spokes).
    if (w.caliper) root.remove(w.caliper);
  }
  // the hood never opens in the game, so the engine bay (~12k triangles) is dropped
  if (v.body){ const eng = root.userData.engine; if (eng && eng.parent) eng.parent.remove(eng); }
  // high-detail fascias, lights, seams, skirts... (built from this shell's own numbers)
  if (P.hd && v.body) addCarDetail(v, v.body, { paint:paintM, tail:tailM });
  body.add(root);

  // synthetic side profile in the old format (+X = front, Y up) so stripes, racks, wings, drivers line up
  const prof = profileFromDesign(P); const L = dims.L, H = dims.H;
  const xOf = u => (u - 0.5) * L - zMid;
  const top = prof.top.map(([u, f]) => [xOf(u), f * H]);
  const bodyPts = [[xOf(1), dims.clear + 0.06], ...top.slice().reverse(), [xOf(0), dims.clear + 0.06]];
  const [uGlass, uRoofR, uRoofF, uCowl] = prof.cab;
  const beltR = prof.belt[0] * H, beltF = prof.belt[1] * H;
  const glassPts = [[xOf(uCowl) - 0.05, beltF], [xOf(uRoofF), H - 0.03], [xOf(uRoofR), H - 0.03], [xOf(uGlass) + 0.05, beltR]];
  const roofPts = [[xOf(uRoofF), H], [xOf(uRoofR), H], [xOf(uRoofR), H - 0.06], [xOf(uRoofF), H - 0.06]];
  const profile = { W:dims.W, wb:Math.abs(dims.axleF - zMid), wheelR:v.wheels[0].radius, track:Math.abs(v.wheels[0].x) * 2,
    body:bodyPts, glass:glassPts, roof:roofPts, forge:true };

  const t = { body, wheels, paintM, glassM, rimM, tailM, profile, frontZ:-(L / 2 - zMid), rearZ:(L / 2 + zMid), roofY:H };
  templates.set(id, t);
  return t;
}

function swapMaterials(obj, map){
  obj.traverse(o => {
    if (!o.isMesh) return;
    if (Array.isArray(o.material)) o.material = o.material.map(m => map.get(m) || m);
    else if (map.has(o.material)) o.material = map.get(o.material);
  });
}

// Build one Forge car for the game. Returns null if Forge can't build in this environment (caller falls back).
export function buildForgeCar(def, colorHex){
  const id = def.id || 'sport';
  let t;
  try { t = templates.get(id) || makeTemplate(id); }
  catch (e){ console.warn('Forge car build failed, using classic model', e); return null; }
  const group = new THREE.Group();
  const paint = t.paintM.clone(); paint.color.setHex(colorHex);
  const glass = t.glassM.clone();
  const rim = t.rimM.clone();
  const tail = t.tailM.clone(); tail.emissive.setHex(0xff1a1a); tail.emissiveIntensity = 1.8;
  const map = new Map([[t.paintM, paint], [t.glassM, glass], [t.rimM, rim], [t.tailM, tail]]);

  const body = t.body.clone(true); swapMaterials(body, map); group.add(body);
  const wheels = t.wheels.map(w => { const c = w.clone(true); swapMaterials(c, map); group.add(c); return c; });
  group.traverse(o => { if (o.isMesh){ o.castShadow = true; o.receiveShadow = false; } });

  group.userData = {
    flashers:null, defId:id, bodyColor:colorHex, wheels,
    frontWheels: wheels.filter(w => w.position.z < 0),
    rim, glass, paint, brakeMats:[tail], setBrake:(on) => { tail.emissiveIntensity = on ? 4.5 : 1.8; },
    profile:t.profile, frontZ:t.frontZ, rearZ:t.rearZ, roofY:t.roofY, forge:true,
  };
  return group;
}

// Free the cached shapes (e.g. after a graphics-quality change).
export function clearForgeCache(){ templates.clear(); }

// ---- static (parked) cars: Forge silhouettes at instancing cost ----
// Hundreds of cars line the curbs, so instead of the full loft (~30k+ triangles each) they get the
// Forge design's own side profile + greenhouse extruded to its width, with simple wheels:
// a few hundred triangles each, ~2 draw calls per body style for the whole city.
const parkedCache = new Map();
function extrudeSide(pts, width, bevel){
  const sh = new THREE.Shape(); sh.moveTo(pts[0][0], pts[0][1]); for (const q of pts.slice(1)) sh.lineTo(q[0], q[1]); sh.closePath();
  const g = new THREE.ExtrudeGeometry(sh, { depth:width - bevel * 2, bevelEnabled:true, bevelThickness:bevel, bevelSize:bevel, bevelSegments:2, curveSegments:4 });
  g.translate(0, 0, -(width - bevel * 2) / 2); g.rotateY(Math.PI / 2);   // +X front -> -Z front
  return g;
}
const strip = g => { g = g.index ? g.toNonIndexed() : g; for (const k of Object.keys(g.attributes)) if (k !== 'position' && k !== 'normal') g.deleteAttribute(k); g.clearGroups(); return g; };
export function forgeParkedGeometry(id){
  if (parkedCache.has(id)) return parkedCache.get(id);
  let out = null;
  try {
    const t = templates.get(id) || makeTemplate(id);
    const P = t.profile;
    const body = extrudeSide(P.body, P.W, 0.06);
    const glass = extrudeSide(P.glass, P.W * 0.86, 0.03);
    const wheels = [];
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) wheels.push(new THREE.CylinderGeometry(P.wheelR, P.wheelR, 0.24, 14).rotateZ(Math.PI / 2).translate(sx * P.track / 2, P.wheelR, sz * P.wb));
    out = { paint:strip(body), dark:mergeGeometries([glass, ...wheels].map(strip), false), profile:P };
  } catch (e){ console.warn('Forge parked car failed', e); out = null; }
  parkedCache.set(id, out);
  return out;
}
